const { summarizeBatch } = require('./solution');
class Record { constructor() { this.batchId = 'b'; this.category = 'c'; this.quantity = 1; } }
let caught; try { summarizeBatch([new Record()], 'b'); } catch (e) { caught = e; }
if (!(caught instanceof TypeError)) throw new Error('Class instance accepted despite plain record requirement');

prompt.text:
Repair the CommonJS module below and return one corrected complete source file. It must export exactly `{ summarizeBatch }`.

`summarizeBatch(records, batchId)` groups matching inventory records by category. `records` must be an array of plain objects `{ batchId, category, quantity }`. Both string fields must be non-empty strings, and `quantity` must be a non-negative safe integer. The requested `batchId` must be a non-empty string.

Validate every record before filtering. For records whose `batchId` exactly matches the requested value, sum quantities by category. Return an array of new objects `{ category, quantity }`, ordered by each category's first appearance among matching records. Categories with a total of zero remain present. If no records match, return an empty array. Do not mutate or alias the input.

Known-bad source:
```javascript
function summarizeBatch(records, batchId) {
  if (!Array.isArray(records) || typeof batchId !== 'string' || batchId.length === 0) {
    throw new TypeError('invalid arguments');
  }
  for (const record of records) {
    if (record === null || typeof record !== 'object' || Array.isArray(record) ||
        typeof record.batchId !== 'string' || record.batchId.length === 0 ||
        typeof record.category !== 'string' || record.category.length === 0 ||
        !Number.isSafeInteger(record.quantity) || record.quantity < 0) {
      throw new TypeError('invalid record');
    }
  }

  const totals = new Map();
  for (const record of records) {
    if (record.batchId !== batchId) continue;
    totals.set(record.category, record.quantity);
  }
  return Array.from(totals, ([category, quantity]) => ({ category, quantity }));
}

module.exports = { summarizeBatch };
```

