'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['summarizeBatch']);
const { summarizeBatch } = api;

assert.deepStrictEqual(summarizeBatch([], 'batch-1'), []);
assert.deepStrictEqual(summarizeBatch([
  { batchId: 'other', category: 'x', quantity: 5 }
], 'batch-1'), []);

const records = [
  { batchId: 'b1', category: 'fruit', quantity: 2 },
  { batchId: 'b2', category: 'fruit', quantity: 100 },
  { batchId: 'b1', category: 'tools', quantity: 0 },
  { batchId: 'b1', category: 'fruit', quantity: 3 },
  { batchId: 'b1', category: 'books', quantity: 4 },
  { batchId: 'b1', category: 'tools', quantity: 7 }
];
const before = records.map((record) => ({ ...record }));
const output = summarizeBatch(records, 'b1');
assert.deepStrictEqual(output, [
  { category: 'fruit', quantity: 5 },
  { category: 'tools', quantity: 7 },
  { category: 'books', quantity: 4 }
]);
assert.deepStrictEqual(records, before);
assert.notStrictEqual(output, records);
assert.notStrictEqual(output[0], records[0]);
output[0].quantity = 999;
assert.equal(records[0].quantity, 2);

assert.deepStrictEqual(summarizeBatch([
  { batchId: 'b', category: 'zero', quantity: 0 }
], 'b'), [{ category: 'zero', quantity: 0 }]);
assert.deepStrictEqual(summarizeBatch([
  { batchId: 'b', category: 'max', quantity: Number.MAX_SAFE_INTEGER }
], 'b'), [{ category: 'max', quantity: Number.MAX_SAFE_INTEGER }]);

for (const badRecords of [null, {}, 'records']) {
  assert.throws(() => summarizeBatch(badRecords, 'b'), TypeError);
}
for (const badBatchId of [undefined, null, '', 1, []]) {
  assert.throws(() => summarizeBatch([], badBatchId), TypeError);
}
for (const record of [
  null, [], new Date(), {},
  { batchId: '', category: 'c', quantity: 1 },
  { batchId: 1, category: 'c', quantity: 1 },
  { batchId: 'b', category: '', quantity: 1 },
  { batchId: 'b', category: 1, quantity: 1 },
  { batchId: 'b', category: 'c', quantity: -1 },
  { batchId: 'b', category: 'c', quantity: 1.5 },
  { batchId: 'b', category: 'c', quantity: NaN },
  { batchId: 'b', category: 'c', quantity: Number.MAX_SAFE_INTEGER + 1 },
  { batchId: 'b', category: 'c', quantity: '1' }
]) {
  assert.throws(() => summarizeBatch([record], 'b'), TypeError);
}
assert.throws(() => summarizeBatch([
  { batchId: 'b', category: 'valid', quantity: 1 },
  { batchId: 'other', category: '', quantity: 1 }
], 'b'), TypeError);
const sparse = new Array(1);
assert.throws(() => summarizeBatch(sparse, 'b'), TypeError);

